const settle = `-- name: Settle :execrows
UPDATE platform_mail_producer_outbox SET state=$4,code=$5,lease_id=NULL,lease_until=NULL,
    attempts=CASE WHEN $6::boolean THEN greatest(0,attempts-1) ELSE attempts END,
    recipient_address=CASE WHEN $4='queued' THEN recipient_address ELSE '' END,
    verification_token_hash=CASE WHEN $4='queued' THEN verification_token_hash ELSE NULL END,
    sealed_verification=CASE WHEN $4='queued' THEN sealed_verification ELSE '' END,
    verification_key_id=CASE WHEN $4='queued' THEN verification_key_id ELSE '' END,
    verification_origin=CASE WHEN $4='queued' THEN verification_origin ELSE '' END,
    next_attempt_at=clock_timestamp()+$7::integer*interval '1 second',updated_at=clock_timestamp(),revision=revision+1
WHERE namespace=$1 AND id=$2 AND lease_id=$3 AND state='claimed'
`

type SettleParams struct {
	Namespace     string
	ID            pgtype.UUID
	LeaseID       pgtype.UUID
	State         string
	Code          string
	RefundAttempt bool
	RetrySeconds  int32
}

func (q *Queries) Settle(ctx context.Context, db DBTX, arg SettleParams) (int64, error) {
	result, err := db.Exec(ctx, settle,
		arg.Namespace,
		arg.ID,
		arg.LeaseID,
		arg.State,
		arg.Code,
		arg.RefundAttempt,
		arg.RetrySeconds,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

